import * as zlib from 'zlib';
import * as crypto from 'crypto';
import { promisify } from 'util';

const inflate = promisify(zlib.inflate);
const deflate = promisify(zlib.deflate);

interface AuthToken {
  userId: string;
  roles: string[];
  exp: number;
  nonce: string;
}

interface CompressedPayload {
  data: Buffer;
  checksum: string;
  originalSize: number;
}

class TokenSizePolicy {
  private readonly maxCompressedSize: number;
  private readonly maxDecompressedSize: number;
  private readonly maxRatio: number;

  constructor(maxCompressed = 4096, maxDecompressed = 65536, maxRatio = 100) {
    this.maxCompressedSize = maxCompressed;
    this.maxDecompressedSize = maxDecompressed;
    this.maxRatio = maxRatio;
  }

  validateCompressed(payload: CompressedPayload): boolean {
    if (payload.data.length > this.maxCompressedSize) {
      return false;
    }
    if (payload.originalSize > this.maxDecompressedSize) {
      return false;
    }
    return true;
  }

  validateRatio(compressedSize: number, decompressedSize: number): boolean {
    const ratio = decompressedSize / compressedSize;
    return ratio <= this.maxRatio;
  }
}

class AuthSessionStore {
  private sessions: Map<string, Buffer> = new Map();
  private readonly hmacKey: Buffer;

  constructor(secret: string) {
    this.hmacKey = crypto.createHash('sha256').update(secret).digest();
  }

  computeChecksum(data: Buffer): string {
    return crypto.createHmac('sha256', this.hmacKey)
      .update(data)
      .digest('hex');
  }

  async storeSession(userId: string, tokenData: Buffer): Promise<CompressedPayload> {
    const compressed = await deflate(tokenData);
    const checksum = this.computeChecksum(compressed);
    this.sessions.set(userId, compressed);
    return {
      data: compressed,
      checksum,
      originalSize: tokenData.length
    };
  }

  getCompressedSession(userId: string): Buffer | undefined {
    return this.sessions.get(userId);
  }
}

class AsyncAuthenticator {
  private store: AuthSessionStore;
  private policy: TokenSizePolicy;
  private inflightDecompressions: Map<string, Promise<Buffer>> = new Map();

  constructor(secret: string) {
    this.store = new AuthSessionStore(secret);
    this.policy = new TokenSizePolicy();
  }

  async createToken(userId: string, roles: string[]): Promise<CompressedPayload> {
    const token: AuthToken = {
      userId,
      roles,
      exp: Date.now() + 3600000,
      nonce: crypto.randomBytes(16).toString('hex')
    };
    const serialized = Buffer.from(JSON.stringify(token), 'utf-8');
    return this.store.storeSession(userId, serialized);
  }

  private async decompressWithDedup(key: string, data: Buffer): Promise<Buffer> {
    const existing = this.inflightDecompressions.get(key);
    if (existing) {
      return existing;
    }
    const promise = inflate(data);
    this.inflightDecompressions.set(key, promise);
    try {
      const result = await promise;
      return result;
    } finally {
      this.inflightDecompressions.delete(key);
    }
  }

  private safeChecksumEqual(expected: string, provided: string): boolean {
    // Validate the provided checksum is a well-formed hex string of the
    // expected length before comparing. timingSafeEqual throws when buffer
    // lengths differ, so we must guard against attacker-supplied lengths.
    if (typeof provided !== 'string' || !/^[0-9a-fA-F]+$/.test(provided)) {
      return false;
    }
    const expectedBuf = Buffer.from(expected, 'hex');
    const providedBuf = Buffer.from(provided, 'hex');
    if (expectedBuf.length !== providedBuf.length) {
      return false;
    }
    return crypto.timingSafeEqual(expectedBuf, providedBuf);
  }

  async validateAndDecodeToken(payload: CompressedPayload): Promise<AuthToken | null> {
    const expectedChecksum = this.store.computeChecksum(payload.data);
    if (!this.safeChecksumEqual(expectedChecksum, payload.checksum)) {
      return null;
    }

    if (!this.policy.validateCompressed(payload)) {
      return null;
    }

    // Deduplication key based on checksum for concurrent requests
    const dedupKey = payload.checksum;
    const decompressed = await this.decompressWithDedup(dedupKey, payload.data);

    // Ratio check uses actual decompressed size for accurate validation
    if (!this.policy.validateRatio(payload.data.length, decompressed.length)) {
      return null;
    }

    const token: AuthToken = JSON.parse(decompressed.toString('utf-8'));
    if (token.exp < Date.now()) {
      return null;
    }
    return token;
  }

  async refreshToken(payload: CompressedPayload): Promise<CompressedPayload | null> {
    const token = await this.validateAndDecodeToken(payload);
    if (!token) return null;
    return this.createToken(token.userId, token.roles);
  }
}

export { AsyncAuthenticator, CompressedPayload, TokenSizePolicy };
